-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.legal_acceptances (
  user_id uuid not null,
  terms_version text not null,
  privacy_version text not null,
  accepted_at timestamp with time zone default now() not null,
  constraint legal_acceptances_pkey PRIMARY KEY (user_id, terms_version, privacy_version),
  constraint legal_acceptances_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint legal_acceptances_privacy_version_check CHECK ((privacy_version ~ '^[0-9]{1,4}([.][0-9]{1,4})?$'::text)),
  constraint legal_acceptances_terms_version_check CHECK ((terms_version ~ '^[0-9]{1,4}([.][0-9]{1,4})?$'::text))
);

CREATE INDEX legal_acceptances_latest ON public.legal_acceptances USING btree (user_id, accepted_at DESC);

CREATE TRIGGER quota_rows AFTER INSERT ON public.legal_acceptances FOR EACH ROW EXECUTE FUNCTION public.quota_rows('100');

alter table public.legal_acceptances enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.legal_acceptances to service_role;
